--[name] 予定薬剤集計(レセ単位)使用数
UPDATE "ntss"."sys_data_list_detail" SET "function_display_sql" = 'select medicine_cd as id, medicine_name as name from mst_medicine where class_cd = -1 and facility_cd = @facilityCd' WHERE "category_cd" = 1 AND "disp_order" = 0;
UPDATE "ntss"."sys_data_list_detail" SET "function_display_sql" = 'select T01.medicine_cd as id,T01.medicine_name as name,T01.class_cd as cd from mst_medicine T01 left join (select row_number() over () as row_num,(value->>''code'')::int as code from mst_selector ms,jsonb_array_elements(ms.order_settings -> ''items'') json_table where ms.facility_cd = @facilityCd and ms.master_physical_name = ''mst_medicine'') as T02 on T01.medicine_cd = T02.code where T01.class_cd in (@ids) and T01.facility_cd = @facilityCd order by T02.row_num, T01.medicine_cd' WHERE "category_cd" = 1 AND "disp_order" = 1;
--[name] 予定薬剤集計(指示単位)使用数
UPDATE "ntss"."sys_data_list_detail" SET "function_display_sql" = 'select medicine_cd as id, medicine_name as name, 1 as kubun from mst_medicine where facility_cd = @facilityCd AND class_cd = -1 union select medicine_mix_cd as id, medicine_mix_name as name, 2 as kubun from mst_medicine_mix where facility_cd = @facilityCd AND class_cd = -1' WHERE "category_cd" = 2 AND "disp_order" = 0;
UPDATE "ntss"."sys_data_list_detail" SET "function_display_sql" = 'select id, name, cd, kubun from(select T01.medicine_cd as id,T01.medicine_name as name,T01.class_cd as cd,1 as kubun,1 as type_code,T02.row_num from mst_medicine T01 left join (select row_number() over () as row_num,(value->>''code'')::int as code from mst_selector ms,jsonb_array_elements(ms.order_settings -> ''items'') json_table where ms.facility_cd = @facilityCd and ms.master_physical_name = ''mst_medicine'') as T02 on T01.medicine_cd = T02.code where T01.class_cd in (@ids) and T01.facility_cd = @facilityCd union select T01.medicine_mix_cd as id,T01.medicine_mix_name as name,T01.class_cd as cd,2 as kubun,2 as type_code,T02.row_num from mst_medicine_mix T01 left join (select row_number() over () as row_num,(value->>''code'')::int as code from mst_selector ms,jsonb_array_elements(ms.order_settings -> ''items'') json_table where ms.facility_cd = @facilityCd and ms.master_physical_name = ''mst_medicine_mix'') as T02 on T01.medicine_mix_cd = T02.code where T01.class_cd in (@ids) and T01.facility_cd = @facilityCd) M01 order by M01.type_code, M01.row_num,	M01.ID' WHERE "category_cd" = 2 AND "disp_order" = 1;
